from pathlib import Path
import json, base64, html, re
r=Path(__file__).parent; p=json.loads((r/'projects.json').read_text()); A=r/'assets'; E=html.escape
u='https://github.com/infinite667'; pages='https://infinite667.github.io/infinite667/'
def img(n,alt,w=None):return f'<img src="assets/{n}.svg" alt="{E(alt)}"'+(f' width="{w}"' if w else ' width="100%"')+'/>'
def link(url,content):return f'<a href="{url.replace("&","&amp;")}">{content}</a>'
readme=f'''<!-- PROJECT: RENEKTON / Command Center — independent fan-inspired profile theme -->
<div align="center">

{img('hero','Murat Mehmeti / infinite667 — Cybersecurity, PowerShell, IT Support')}

{img('stats','16 public repositories (snapshot), 6 featured projects, 4 verified links, 2 links to confirm')}

[Overview](#command-center) · [Top repositories](#top-repositories) · [Technologies](#technologies) · [GitHub activity]({u}#contribution-activity) · [Interactive dashboard]({pages})

</div>

## Command Center

<div align="center">
{img('about','About — security-minded IT professional', '49%')}
{img('focus','Current focus — security research, privacy, automation, authorized labs', '49%')}
</div>

## Top repositories

{img('repos-title','Top repositories — select a module')}

'''
for i in range(0,len(p),2):
 readme+='<p align="center">\n'+ '\n'.join(link(a['url'],img('repo-'+a['id'],a['name']+' — '+ ' '.join(a['lines']),'49%')) for a in p[i:i+2])+'\n</p>\n\n'
readme+='''<details>
<summary><b>Security research / project index</b></summary>

'''
for a in p:readme+=f'- [{a["name"]}]({a["url"]}): {" ".join(a["lines"])}\n'
readme+=f'''
Research and testing should be conducted only in authorized environments. See the individual repositories for project scope, licensing and security policies.

</details>

## Technologies

<p align="center">
{img('technology','Python, PowerShell, TypeScript, Shell, Go, Git and Windows','49%')}
{link(u+'#contribution-activity',img('activity','View GitHub contribution activity','49%'))}
</p>

<details>
<summary><b>About this command center</b></summary>

An independent profile design inspired by the colors and mechanical armor of PROJECT: Renekton. It is not affiliated with Riot Games. Public repository count is a snapshot from November 25, 2026; project cards are curated, not ranked by stars. Unconfirmed project links open a repository search. The separate dashboard provides filtering, tabs and live public-data refresh when available.

</details>

{link(u,img('footer','Research. Build. Secure. — infinite667'))}
'''
(r/'README.md').write_text(readme)
# Standalone HTML uses embedded SVGs so it works offline. GitHub links and optional refresh require network.
def data(n):return 'data:image/svg+xml;base64,'+base64.b64encode((A/(n+'.svg')).read_bytes()).decode()
assets={n.stem:data(n.stem) for n in A.glob('*.svg')}
jsdata=json.dumps({'projects':p,'assets':assets},ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PROJECT: RENEKTON — Command Center</title><style>
:root{color-scheme:dark;--bg:#0b0c10;--panel:#14161d;--text:#f3f3f7;--muted:#a9adbb;--hot:#ffae24;--line:#555461}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#29232a,#0b0c10 65%);color:var(--text);font:14px system-ui,sans-serif}body.light{color-scheme:light;--bg:#ece9e2;--panel:#fff;--text:#25252c;--muted:#4f505c;--hot:#ac4800;--line:#c1b8ab;background:#ece9e2}a{color:var(--hot);text-decoration:none}a:hover{text-decoration:underline}button,input,select{font:inherit}button,select,input{background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:5px;padding:9px 13px}button{cursor:pointer}button:hover,button[aria-pressed=true],button[aria-selected=true]{border-color:var(--hot);color:var(--hot);box-shadow:inset 0 -2px var(--hot),0 0 14px #ff8a1625}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--hot);outline-offset:3px}header{border-bottom:1px solid #724c24;padding:12px 0;background:#101117}header .bar{max-width:1120px;margin:auto;display:flex;align-items:center;gap:12px;padding:0 15px;color:#f3f3f7}.brand{font-weight:800;letter-spacing:1px}.brand em{color:#ffae24;font-style:normal}.spacer{flex:1}.kicker{font:11px monospace;letter-spacing:2px;color:var(--hot)}main{max-width:1120px;margin:16px auto;padding:0 15px}.asset{display:block;width:100%;height:auto}.hero{position:relative}.statrow{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:9px 0}.stat{padding:13px 16px;background:linear-gradient(135deg,#282933,#13151b);border:1px solid #655043;clip-path:polygon(12px 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%,0 12px);color:#f3f3f7}.stat strong{font-size:27px;color:#ffcc5a;display:block}.stat small{font:10px monospace;letter-spacing:1px;color:#b5b8c4}.nav{display:flex;gap:7px;flex-wrap:wrap;border-bottom:1px solid #795026;padding:8px 0;margin:6px 0 16px}.layout{display:grid;grid-template-columns:28% 1fr;gap:12px}.side{display:grid;align-content:start;gap:10px}.panel{border:1px solid var(--line);background:var(--panel);position:relative;padding:16px;clip-path:polygon(13px 0,100% 0,100% calc(100% - 13px),calc(100% - 13px) 100%,0 100%,0 13px);box-shadow:inset 0 1px #ff9b1950}.panel h2{font-size:16px;margin:0 0 13px}.panel h2:before{content:'// ';color:var(--hot)}.panel p{color:var(--muted);line-height:1.55}.controls{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 12px}.controls input{flex:1;min-width:130px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:9px}.repo{border:1px solid transparent;transition:transform .2s,filter .2s;min-width:0}.repo:hover{transform:translateY(-2px);filter:drop-shadow(0 0 6px #ff9b1955)}.repo details{background:var(--panel);border:1px solid var(--line);margin:4px 3px 0;padding:8px 10px;color:var(--muted);font-size:12px}.repo summary{cursor:pointer;color:var(--text)}.repo details a{display:inline-block;margin-top:6px}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.radar{width:128px;aspect-ratio:1;margin:8px auto 15px;border-radius:50%;position:relative;background:repeating-radial-gradient(circle,transparent 0 19px,#ff9b193c 20px 21px),linear-gradient(90deg,transparent 49.5%,#ff9b1940 50%,transparent 50.5%),linear-gradient(0deg,transparent 49.5%,#ff9b1940 50%,transparent 50.5%),#16181b;border:1px solid #b16c20;overflow:hidden}.radar:after{content:'';position:absolute;inset:0;background:conic-gradient(from 0deg,transparent 0 290deg,#ff8a1166 359deg,#ffe16a 360deg);animation:rotate 4s linear infinite}.radar i{position:absolute;width:6px;height:6px;background:#ffba3e;box-shadow:0 0 8px #ff9b19;z-index:1;transform:rotate(45deg)}@keyframes rotate{to{transform:rotate(360deg)}}.paused *,.paused *:before,.paused *:after{animation-play-state:paused!important}.paused .asset{filter:none}.status{font-size:11px;color:var(--muted);margin:12px 0}.activity-list{padding:0;list-style:none}.activity-list li{padding:9px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.footer{margin-top:14px}.heat{display:grid;grid-auto-flow:column;grid-template-rows:repeat(7,1fr);gap:3px;width:100%;aspect-ratio:4.2}.heat span{background:#32323e;border-radius:2px}.heat span[data-v='1']{background:#643d26}.heat span[data-v='2']{background:#ae5d1d}.heat span[data-v='3']{background:#ff9717}.heat span[data-v='4']{background:#ffdb55}.lang{display:flex;gap:8px;align-items:center;margin:12px 0}.lang span{width:80px}.track{flex:1;background:#343643;height:7px;border-radius:4px;overflow:hidden}.track i{display:block;height:100%;background:linear-gradient(90deg,#ff6b11,#ffd34b)}.hidden{display:none!important}@media(max-width:760px){.layout{grid-template-columns:1fr}.side{grid-template-columns:1fr 1fr}.side .panel{display:none}.bottom{grid-template-columns:1fr}.statrow{grid-template-columns:1fr 1fr}.bar .kicker{display:none}.cards{grid-template-columns:1fr 1fr}}@media(max-width:480px){.cards{grid-template-columns:1fr}.side{grid-template-columns:1fr}.nav button{padding:7px}.bottom{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
</style></head><body><header><div class="bar"><span class="brand"><em>///</em> INFINITE667</span><span class="kicker">PROJECT: RENEKTON / COMMAND CENTER</span><span class="spacer"></span><a href="https://github.com/infinite667" target="_blank" rel="noopener">GitHub ↗</a></div></header><main><div class="hero" id="hero"></div><div class="statrow" id="stats"></div><nav class="nav" aria-label="Dashboard sections"><button data-tab="overview" aria-selected="true">Overview</button><button data-tab="repositories" aria-selected="false">Repositories</button><button data-tab="activity" aria-selected="false">Activity</button><span class="spacer"></span><button id="motion" aria-pressed="true">FX on</button><button id="theme" aria-pressed="false">Light UI</button><button id="refresh">Refresh GitHub data</button></nav><div class="layout"><aside class="side" id="side"><div id="about"></div><div id="focus"></div><div id="tech"></div><div class="panel"><h2>Command center</h2><div class="radar" aria-label="Decorative animated radar"><i style="top:25%;left:36%"></i><i style="top:55%;left:72%"></i><i style="top:68%;left:29%"></i></div><p><span style="color:var(--hot)">◆</span> Interface ready</p><small>Visual effect only — not a real security scan.</small></div></aside><section><div class="panel" id="repositories"><h2>Top repositories</h2><div class="controls" id="controls"><input id="search" type="search" placeholder="Find a repository…" aria-label="Find a repository"><select id="sort" aria-label="Sort repositories"><option value="featured">Featured order</option><option value="name">Name A–Z</option><option value="stars">Stars (when loaded)</option></select></div><div class="controls" id="filters"></div><div class="cards" id="cards"></div><div class="status" id="count"></div></div><div class="bottom" id="analytics"><div class="panel"><h2>Languages & technologies</h2><div id="languages"><p>Python · PowerShell · TypeScript · Shell · Go</p><p>Refresh public data to see repository language counts.</p></div></div><div class="panel"><h2>Contribution activity</h2><p>GitHub’s actual contribution matrix is available on the profile. No simulated contributions are displayed.</p><a href="https://github.com/infinite667#contribution-activity" target="_blank" rel="noopener">Open real contribution graph ↗</a></div></div><div class="panel" id="activity" style="margin-top:12px"><h2>Recent public activity</h2><ul class="activity-list" id="events"><li>Refresh GitHub data to load recent public events.</li></ul><a href="https://github.com/infinite667" target="_blank" rel="noopener">Open GitHub profile ↗</a></div></section></div><div class="status" id="status" role="status">Offline preview · public repo count is a November 25, 2026 snapshot · live data not loaded.</div><div class="footer" id="footer"></div></main><script>
const DATA=__DATA__;const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const asset=(n,alt)=>`<img class="asset" src="${DATA.assets[n]}" alt="${esc(alt)}">`;let category='All',live={},allRepos=null,tab='overview';let motion=true;const base='https://api.github.com';const user='infinite667';
for(const [id,n,alt] of [['hero','hero','Murat Mehmeti, infinite667'],['about','about','About'],['focus','focus','Current focus'],['tech','technology','Technologies'],['footer','footer','Research. Build. Secure.']]) $(id).innerHTML=asset(n,alt);
function stats(profile){const s=[[profile?.public_repos??16,'PUBLIC REPOS'+(profile?'':'*')],[DATA.projects.length,'FEATURED MODULES'],[profile?.followers??'—','FOLLOWERS'],[profile?.following??'—','FOLLOWING']];$('stats').innerHTML=s.map(([a,b])=>`<div class="stat"><strong>${esc(a)}</strong><small>${esc(b)}</small></div>`).join('')}
function render(){const q=$('search').value.toLowerCase();let ps=DATA.projects.filter(p=>(category==='All'||p.category===category)&&[p.name,p.category,...p.lines].join(' ').toLowerCase().includes(q));if($('sort').value==='name')ps.sort((a,b)=>a.name.localeCompare(b.name));if($('sort').value==='stars')ps.sort((a,b)=>(live[b.id]?.stargazers_count??-1)-(live[a.id]?.stargazers_count??-1));$('cards').innerHTML=ps.map(p=>{const v=live[p.id];const href=v?.html_url||p.url;return `<article class="repo"><a href="${esc(href)}" target="_blank" rel="noopener">${asset('repo-'+p.id,p.name+' — '+p.lines.join(' '))}</a><details><summary>Module details${v?' · ★ '+esc(v.stargazers_count)+' · forks '+esc(v.forks_count):''}</summary><p>${esc(v?.description||p.lines.join(' '))}</p><a href="${esc(href)}" target="_blank" rel="noopener">${p.verified||v?'Open repository':'Find repository'} ↗</a></details></article>`}).join('')||'<p>No matching modules.</p>';$('count').textContent=`${ps.length} of ${DATA.projects.length} featured modules`}
for(const c of ['All','Security','Privacy','Research']){const b=document.createElement('button');b.textContent=c;b.setAttribute('aria-pressed',c==='All');b.onclick=()=>{category=c;for(const x of $('filters').children)x.setAttribute('aria-pressed',x===b);render()};$('filters').append(b)}$('search').oninput=render;$('sort').onchange=render;
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{tab=b.dataset.tab;for(const x of document.querySelectorAll('[data-tab]'))x.setAttribute('aria-selected',x===b);$('repositories').classList.toggle('hidden',tab==='activity');$('analytics').classList.toggle('hidden',tab==='repositories');$('activity').classList.toggle('hidden',tab==='repositories');$('side').classList.toggle('hidden',tab==='activity');document.querySelector('.layout').style.gridTemplateColumns=tab==='activity'?'1fr':''};
$('theme').onclick=()=>{const light=document.body.classList.toggle('light');$('theme').textContent=light?'Dark UI':'Light UI';$('theme').setAttribute('aria-pressed',light)};
// Replace animated SVGs with equivalent SVGs containing disabled animation when FX is off.
$('motion').onclick=()=>{motion=!motion;document.body.classList.toggle('paused',!motion);$('motion').textContent=motion?'FX on':'FX off';$('motion').setAttribute('aria-pressed',motion);for(const im of document.querySelectorAll('img.asset')){if(!im.dataset.original)im.dataset.original=im.src;im.src=motion?im.dataset.original:'data:image/svg+xml;base64,'+btoa(atob(im.dataset.original.split(',')[1]).replaceAll('animation:','animation:none;--disabled-animation:'))}};
async function get(path){const r=await fetch(base+path,{headers:{Accept:'application/vnd.github+json'}});if(!r.ok)throw Error('GitHub HTTP '+r.status);return r.json()}
$('refresh').onclick=async()=>{const b=$('refresh');b.disabled=true;$('status').textContent='Requesting public GitHub data…';try{const [profile,repos]=await Promise.all([get('/users/'+user),get('/users/'+user+'/repos?per_page=100')]);allRepos=repos;stats(profile);for(const p of DATA.projects){const match=repos.find(r=>r.name.toLowerCase().replace(/[^a-z0-9]/g,'')===p.name.toLowerCase().replace(/[^a-z0-9]/g,''));if(match)live[p.id]=match}render();const langs={};for(const r of repos)if(r.language)langs[r.language]=(langs[r.language]||0)+1;$('languages').innerHTML=Object.entries(langs).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([l,n])=>`<div class="lang"><span>${esc(l)}</span><div class="track"><i style="width:${n/Math.max(1,repos.length)*100}%"></i></div><b>${n}</b></div>`).join('')||'<p>No public language data.</p>';$('languages').innerHTML+='<small>Counts of fetched repositories by primary language (not skill ratings).</small>';$('status').textContent='Public profile and repository data loaded · '+new Date().toLocaleString();try{const ev=await get('/users/'+user+'/events/public?per_page=10');$('events').innerHTML=ev.slice(0,5).map(e=>`<li>${esc(e.type.replace(/Event$/,''))} · ${esc(e.repo.name)} <small>${esc(new Date(e.created_at).toLocaleDateString())}</small></li>`).join('')||'<li>No recent public events returned.</li>'}catch(e){$('events').innerHTML='<li>Public events unavailable.</li>'}}catch(e){$('status').textContent='Live refresh unavailable: '+e.message+' · existing preview retained.'}finally{b.disabled=false}};stats();render();
</script></body></html>'''.replace('__DATA__',jsdata)
# Make images respect current motion setting even after re-rendering.
page=page.replace('const asset=(n,alt)=>`<img class="asset" src="${DATA.assets[n]}" alt="${esc(alt)}">`','const asset=(n,alt)=>`<img class="asset" data-original="${DATA.assets[n]}" src="${motion?DATA.assets[n]:\'data:image/svg+xml;base64,\'+btoa(atob(DATA.assets[n].split(\',\')[1]).replaceAll(\'animation:\',\'animation:none;--disabled-animation:\'))}" alt="${esc(alt)}">`')
(r/'index.html').write_text(page)
(r/'SETUP.md').write_text('''# Install PROJECT: RENEKTON — Command Center\n\n1. Back up the existing README in https://github.com/infinite667/infinite667.\n2. Copy README.md and the entire assets/ directory to the root of that existing repository. Commit changes.\n3. Optional: copy index.html to the root as well. In Settings → Pages, select Deploy from a branch, choose the default branch and /(root), and save. Once Pages publishes, the README dashboard link will work. If you do not enable Pages, remove the Interactive dashboard link from README.md.\n4. Open index.html locally to preview without deployment. Refresh GitHub data is opt-in and contacts GitHub's public REST API. GitHub API rate limits and browser/network policies apply.\n5. Confirm the exact repository names for RogueCat and conspy-shell; until then their links intentionally open a repository search. Edit projects.json and rebuild assets if desired (Python 3, Pillow; run python build.py then python finish.py). Update the snapshot manually in build.py/finish.py when needed.\n\nThe native README uses local SVG images, normal links and details sections, with no scripts, tokens, third-party stats service or workflow. Animations depend on GitHub/browser SVG rendering. The interactive UI is separate; it cannot replace GitHub's own navigation or CSS. The graphical armor assets are cropped from the generated reference mockup. This is a fan-inspired design, not an official Riot Games product.\n''')
